import bpy

name='Lacerda_Upper_Blockout'
coll=bpy.data.collections.get(name)
if not coll:
    raise RuntimeError(f'Collection {name} not found')

coll.hide_viewport=False
coll.hide_render=False
try:
    coll.hide_select=False
except Exception:
    pass

objs=list(coll.objects)
for o in objs:
    o.hide_set(False)
    o.hide_viewport=False
    o.hide_render=False

bpy.ops.object.select_all(action='DESELECT')
for o in objs:
    try:
        o.select_set(True)
    except Exception:
        pass
if objs:
    bpy.context.view_layer.objects.active=objs[0]

# Put 3D cursor at the center of the blockout.
bpy.context.scene.cursor.location=(0.0,0.0,10.0)

framed=0
for window in bpy.context.window_manager.windows:
    screen=window.screen
    for area in screen.areas:
        if area.type!='VIEW_3D':
            continue
        region=next((r for r in area.regions if r.type=='WINDOW'),None)
        if not region:
            continue
        space=area.spaces.active
        try:
            with bpy.context.temp_override(window=window, screen=screen, area=area, region=region):
                bpy.ops.view3d.view_selected(use_all_regions=False)
            if hasattr(space,'region_3d'):
                space.region_3d.view_distance=32.0
            framed+=1
        except Exception as e:
            print('frame warning', e)

print(f'Visible objects: {len(objs)}; framed VIEW_3D areas: {framed}; bounds approx X[-24,24] Y[-17,17] Z[-0.36,19.85]')
